"""Shared type scale for the workbench, Chat and its settings surfaces."""

TYPOGRAPHY_CSS = '''
:root{--ui-font:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;--ui-mono:ui-monospace,SFMono-Regular,Consolas,monospace;--ui-body:13px;--ui-meta:12px;--ui-label:14px;--ui-section:16px;--ui-dialog:18px;--ui-title:22px;font-family:var(--ui-font);font-size:var(--ui-body);line-height:1.65;font-synthesis:none}
body{font-family:var(--ui-font);font-size:var(--ui-body);font-weight:400;line-height:1.65}
button,input,select,textarea{font-family:var(--ui-font);font-size:var(--ui-body);line-height:1.5;letter-spacing:normal}button{font-weight:500}input,select,textarea{font-weight:400}button.primary,.primary{font-size:var(--ui-body);font-weight:600}
h1{font-size:var(--ui-title);line-height:1.45;font-weight:600}h2{font-size:var(--ui-dialog);line-height:1.5;font-weight:600}h3{font-size:var(--ui-section);line-height:1.5;font-weight:600}h4{font-size:var(--ui-label);line-height:1.5;font-weight:600}strong,b{font-weight:600}small{font-size:var(--ui-meta);line-height:1.6}
pre,code{font-family:var(--ui-mono);font-size:var(--ui-meta);line-height:1.7}pre{tab-size:2}.brand{font-size:var(--ui-section);font-weight:600;line-height:1.5}nav a,.nav-link{font-size:var(--ui-body);font-weight:500;line-height:1.5}summary{font-size:var(--ui-body);line-height:1.6}
'''

